    # =========================================================================
    # CHAPTER 13: 10 REAL-WORLD FIELD SCENARIOS & TROUBLESHOOTING
    # =========================================================================
    add_h1("অধ্যায় ১৩: বাস্তবভিত্তিক ফিল্ড সিনারিও ও ট্রাবলশুটিং", "ch_13")
    add_body("টেলিকম অপারেশন্স, এনওসি (NOC) এবং ফিল্ড মেইনটেন্যান্সে প্রকৌশলীরা প্রতিদিন যেসব বাস্তব সমস্যার মুখোমুখি হন, সেগুলোর ১০টি পূর্ণাঙ্গ সমাধান কেস-স্টাডি।")

    add_h2("১৩.১ সিনারিও ১: মোবাইল কল ড্রপ তদন্ত ও আরএফ অপটিমাইজেশন", "sec_13_1")
    add_bullet("কল ড্রপের মূল কারণসমূহ:",
        "১. কভারেজ হোল (Coverage Hole): উঁচু ভবন বা পাহাড়ি বাধার কারণে সিগন্যাল লেভেল রিসিভার থ্রেশহোল্ডের নিচে নেমে যাওয়া।\n"
        "২. হ্যান্ডওভার ফেইলিউর (Handover Failure): দ্রুতগামী যানবাহনে এক সেল থেকে অন্য সেলে যাওয়ার সময় টার্গেট সেলে কোনো ফ্রি ভয়েস চ্যানেল না থাকা।\n"
        "৩. কো-চ্যানেল ইন্টারফারেন্স (High Interference / Pilot Pollution)।\n"
        "৪. টাওয়ারের আরএফ ফিডার বা জাম্পার ক্যাবলে ভিএসডব্লিউআর (VSWR) ফল্ট।"
    )
    add_bullet("সমাধান কৌশল:",
        "আরএফ ড্রাইভ টেস্ট (Drive Test) চালিয়ে অ্যান্টেনার টিল্ট (Mechanical & Electrical Tilt) সমন্বয় করা, নেইবার সেল রিলেশন (Neighbor List) আপডেট করা এবং ট্রাফিক বেশি হলে অতিরিক্ত ক্যারিয়ার ফ্রিকোয়েন্সি বা স্মল সেল যোগ করা।"
    )

    add_h2("১৩.২ সিনারিও ২: অপটিক্যাল ফাইবারে কাট পড়লে OTDR দিয়ে ফল্ট শনাক্তকরণ", "sec_13_2")
    add_bullet("ট্রাবলশুটিং ধাপসমূহ:",
        "১. ওটিডিআর (OTDR) এর সাথে টেস্ট জাম্পার ক্যাবল দিয়ে ফাইবার পোর্ট যুক্ত করা।\n"
        "২. ফাইবারের প্রতিসরাঙ্ক (IOR: যেমন 1.4682) এবং পালস উইডথ সেট করে লেজার পালস ফায়ার করা।\n"
        "৩. ওটিডিআর স্ক্রিনে ব্যাকস্ক্যাটার গ্রাফের হঠাৎ ড্রপ বা বড় রিফ্লেক্টিভ স্পাইক (Fresnel Reflection) পর্যবেক্ষণ করা। ওটিডিআর স্বয়ংক্রিয়ভাবে কাট পয়েন্টের দূরত্ব (যেমন: 23.456 কিমি) প্রদর্শন করবে।\n"
        "৪. ফাইবার রুট ম্যাপ ও জিপিএস কো-অর্ডিনেট দেখে ফিল্ড স্প্লাইসিং টিম পাঠিয়ে ফিউশন স্প্লাইসিংয়ের মাধ্যমে ফাইবার পুনরায় জোড়া লাগানো।"
    )

    add_h2("১৩.৩ সিনারিও ৩: টেলিকম সাইটে পাওয়ার ফেইলিউর ও ব্যাটারি ব্যাকআপ ম্যানেজমেন্ট", "sec_13_3")
    add_body("বিটিএস সাইটে বাণিজ্যিক এসি গ্রিড ফেইল করলে সাথে সাথে ব্যাটারি ব্যাংক স্বয়ংক্রিয়ভাবে লোড হ্যান্ডেল করে। যদি ৪ ঘণ্টার বেশি সময় বিদ্যুৎ না থাকে, তবে এনওসি (NOC) অ্যালার্ম পাওয়ার সাথে সাথে পোর্টেবল ডিজেল জেনারেটর (DG) পাঠিয়ে রেকটিফায়ারে এসি ইনপুট দিয়ে ব্যাটারি রিচার্জ ও সাইট সচল রাখা হয়।")

    add_h2("১৩.৪ সিনারিও ৪: অ্যান্টেনা ফিডার ক্যাবলে হাই VSWR অ্যালার্ম সমাধান", "sec_13_4")
    add_body("বিটিএস টাওয়ারে VSWR > 1.4 হলে ট্রান্সমিশন পাওয়ারের বড় অংশ প্রতিফলিত হয়ে রেডিও মডিউল (RRU) অতিরিক্ত উত্তপ্ত হতে পারে। ট্রাবলশুটিং ধাপ:\n"
             "১. সাইট মাস্টার (Site Master / Cable & Antenna Analyzer) দিয়ে Distance-to-Fault (DTF) টেস্ট চালানো।\n"
             "২. জাম্পার ক্যাবল বা কানেক্টরে পানি ঢুকেছে কি না তা পরীক্ষা করা (বৃষ্টির পর এটি সর্বাধিক ঘটে)।\n"
             "৩. ক্ষতিগ্রস্ত কানেক্টর কেটে নতুন কানেক্টর লাগিয়ে প্রপার ওয়েদারপ্রুফিং টেপ দিয়ে সিল করা।")

    add_h2("১৩.৫ সিনারিও ৫: বিজিপি রুট ফ্ল্যাপিং (BGP Route Flapping) সমাধান", "sec_13_5")
    add_body("আইএসপি ব্যাকবোনে কোনো অপটিক্যাল লিঙ্কের সামান্য লুজ কানেকশনের কারণে লিঙ্কটি প্রতি মিনিটে আপ-ডাউন (Flapping) হতে পারে। এর ফলে রাউটার বারবার পুরো রাউটিং টেবিল আপডেট করে সিপিইউ লোড ১০০% এ পৌঁছে ক্র্যাশ করতে পারে। সমাধান: BGP Route Dampening সক্রিয় করা, যাতে ফ্ল্যাপিং রুটকে সাময়িকভাবে পেনাল্টি দিয়ে দমিয়ে রাখা হয়।")

    add_h2("১৩.৬ সিনারিও ৬: ডিডব্লিউডিএম লিঙ্কে ওএসএনআর (OSNR) ড্রপ সমাধান", "sec_13_6")
    add_body("লং-হল ব্যাকবোনে অপটিক্যাল সিগন্যাল-টু-নয়েজ রেশিও (OSNR) কমে গেলে বিট এরর রেট (BER) মারাত্মক বেড়ে যায়। সমাধান: অপটিক্যাল স্পেকট্রাম অ্যানালাইজার (OSA) দিয়ে প্রতিটি চ্যানেলের পাওয়ার লেভেল যাচাই করে EDFA অ্যামপ্লিফায়ারের গেইন টিল্ট সমন্বয় করা এবং ডাইনামিক গেইন ইকুয়ালাইজার (DGE) ব্যবহার করা।")

    add_h2("১৩.৭ সিনারিও ৭: মনসুন মৌসুমে মাইক্রোওয়েভ ফেইড অ্যালার্ম হ্যান্ডলিং", "sec_13_7")
    add_body("প্রবল বর্ষণে উচ্চ ফ্রিকোয়েন্সির (15 GHz+) মাইক্রোওয়েভ লিঙ্কে রেইন অ্যাটেনুয়েশন বেড়ে লিঙ্ক ডাউন হতে পারে। সমাধান: অ্যাডাপ্টিভ মডুলেশন (ACM) সক্রিয় করা, যা বৃষ্টির সময় মডুলেশনকে স্বয়ংক্রিয়ভাবে 256-QAM থেকে নামিয়ে BPSK বা QPSK তে নামিয়ে এনে লিঙ্ক সচল রাখে।")

    add_h2("১৩.৮ সিনারিও ৮: VoLTE কলে ওয়ান-ওয়ে অডিও (One-Way Audio) সমস্যা", "sec_13_8")
    add_body("গ্রাহক কথা বলতে পারেন কিন্তু অপর প্রান্তের কথা শুনতে পান না। এটি সাধারণত ফায়ারওয়াল বা NAT এর কারণে RTP (Real-time Transport Protocol) ইউডিপি পোর্ট ব্লক থাকার কারণে ঘটে। সমাধান: SBC (Session Border Controller) এ এসআইপি অ্যালগ (SIP ALG) বন্ধ করে প্রপার মিডিয়া প্রক্সি রাউটিং নিশ্চিত করা।")

    add_h2("১৩.৯ সিনারিও ৯: আর্থিং রেজিস্ট্যান্স বৃদ্ধি ও বজ্রপাতে ইকুইপমেন্ট সুরক্ষা", "sec_13_9")
    add_body("শুকনো মৌসুমে মাটির আর্দ্রতা কমে আর্থ রেজিস্ট্যান্স ৫ ওহমে উঠে যেতে পারে। সমাধান: আর্থ পিটে কেমিক্যাল যৌগ (বেন্টোনাইট মাটি ও কাঠকয়লা-লবণ মিশ্রণ) দিয়ে মাটির রেজিস্টিভিটি কমানো এবং একাধিক আর্থ পিটকে কপার রিং দিয়ে সমান্তরালে যুক্ত করা।")

    add_h2("১৩.১০ সিনারিও ১০: স্পেকট্রাম অ্যানালাইজার দিয়ে অবৈধ আরএফ ইন্টারফারেন্স ট্র্যাকিং", "sec_13_10")
    add_body("শহরে অবৈধ সিগন্যাল বুস্টার বা জ্যামারের কারণে মোবাইল টাওয়ারের আপলিঙ্কে তীব্র ইন্টারফারেন্স তৈরি হয়ে পুরো এলাকার কল ড্রপ হতে পারে। সমাধান: হ্যান্ডহেল্ড স্পেকট্রাম অ্যানালাইজার ও ডিরেকশনাল ইয়াগি অ্যান্টেনা নিয়ে গাড়িতে ড্রাইভ করে সর্বোচ্চ সিগন্যাল শক্তি ট্র্যাক করে অবৈধ বুস্টার শনাক্ত ও বিটিআরসির সহায়তায় জব্দ করা।")

    add_back_to_toc()
    doc.add_page_break()

